begin;
do $$ begin
  if current_database() !~ '^rigorous_ux_shipping_' or not exists(select 1 from staging_guard.identity where task='shipping-20261010') then
    raise exception 'DISPOSABLE_LOCAL_DATABASE_REQUIRED';
  end if;
end $$;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions, pg_temp;
select no_plan();
insert into auth.users(id,email) values
 ('00000000-0000-4000-8000-000000101001','shipping-owner@test.local'),
 ('00000000-0000-4000-8000-000000101002','shipping-staff@test.local');
update public.store_users set active=true,role='owner' where user_id='00000000-0000-4000-8000-000000101001';
update public.store_users set active=true,role='staff' where user_id='00000000-0000-4000-8000-000000101002';
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000101001',true);
create temp table fixture(name text primary key, value jsonb);
insert into fixture values('product',public.save_product('{"sku":"SHIPPING_TEST","slug":"shipping-test","name":"Prueba de envío","presentation":"1 unidad","description":"Fixture aislado","category":"QA","priceCents":150000,"currentCostCents":100000,"reorderPoint":0,"safetyStock":0,"leadTimeDays":1,"imageUrl":"/test.svg","imageAlt":"Producto de prueba","featured":false,"published":true,"active":true}'));
select public.adjust_product_stock((select (value->>'id')::uuid from fixture where name='product'),4,'Fixture aislado');
insert into fixture values('purchase',public.create_purchase(jsonb_build_object('supplierName','QA','items',jsonb_build_array(jsonb_build_object('productId',(select value->>'id' from fixture where name='product'),'quantity',10,'unitCostCents',1070000)))));
create function pg_temp.order_input(source text, qty integer, protocol uuid default gen_random_uuid()) returns jsonb language sql as $$
 select jsonb_build_object('stockSource',source,'customerName','Cliente QA','paymentMethod','cash','deliveryMethod','pickup','shippingType',null,'shippingFeeCents',0,'quotedSubtotalCents',150000*qty,'quotedTotalCents',150000*qty,'protocolOrderId',protocol,'protocolChecksum','1234ABCD','lines',jsonb_build_array(jsonb_build_object('productId',(select value->>'id' from fixture where name='product'),'quantity',qty,'unitPriceCents',150000)));
$$;
create function pg_temp.id(name text) returns uuid language sql as $$ select (value->>'id')::uuid from fixture where fixture.name=$1 $$;
insert into fixture values('incoming_input',pg_temp.order_input('incoming_only',3));
insert into fixture values('incoming',public.confirm_imported_order((select value from fixture where name='incoming_input')));
select is((select on_hand from public.stock_balances where product_id=pg_temp.id('product')),4,'Incoming-only preserves physical stock');
select is((select reserved from public.stock_balances where product_id=pg_temp.id('product')),0,'Incoming-only does not reserve physical stock');
select is((select sum(quantity) from public.stock_reservations where order_id=pg_temp.id('incoming') and source_type='incoming'),3::bigint,'Only incoming reservations');
select is((select value->>'stockReadiness' from fixture where name='incoming'),'waiting_incoming','Waiting even when physical stock exists');
select is((select value->>'costTotalCents' from fixture where name='incoming'),'3210000','Cost snapshot uses supplier batch');
select is(public.confirm_imported_order((select value from fixture where name='incoming_input'))->>'alreadyImported','true','Creation retry returns same order');
select throws_ok($$select public.confirm_imported_order((select value||'{"stockSource":"normal"}'::jsonb from fixture where name='incoming_input'))$$,'P0001','IDEMPOTENCY_KEY_REUSE_MISMATCH','Retry cannot change stock source');
insert into fixture values('normal',public.confirm_imported_order(pg_temp.order_input('normal',2)));
insert into fixture values('mixed',public.confirm_imported_order(pg_temp.order_input('normal',5)));
select is((select reserved from public.stock_balances where product_id=pg_temp.id('product')),4,'Normal uses physical stock first');
select is((select value->>'costTotalCents' from fixture where name='mixed'),'3410000','Mixed batches preserve exact cost');
select throws_ok($$select public.confirm_imported_order(pg_temp.order_input('incoming_only',5))$$,'P0001','INSUFFICIENT_INCOMING_STOCK','No oversell of inbound capacity');
select is((select count(*) from public.orders),3::bigint,'Failed creation rolls back header and reservations');
select throws_ok($$select public.transition_order(pg_temp.id('incoming'),'mark_delivered')$$,'P0001','CANNOT_DELIVER_ORDER_WAITING_FOR_STOCK','Physical shelf stock cannot deliver incoming-only order early');
insert into fixture values('fee_input',jsonb_build_object('orderId',pg_temp.id('incoming'),'operationId',gen_random_uuid(),'expectedRevision',0,'method','manual','amountCents',1250000));
select is(public.save_order_shipping_fee((select value from fixture where name='fee_input'))->>'totalCents','1700000','Pickup total includes administrative shipping fee');
select is(public.save_order_shipping_fee((select value from fixture where name='fee_input'))->>'shippingFeeRevision','1','Same request does not apply twice');
select is((select count(*) from public.order_shipping_fee_events),1::bigint,'One fee audit event per retry');
select throws_ok($$select public.save_order_shipping_fee((select value||'{"amountCents":100}' from fixture where name='fee_input'))$$,'P0001','IDEMPOTENCY_KEY_REUSE_MISMATCH','Retry cannot change fee amount');
select throws_ok($$select public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('incoming'),'operationId',gen_random_uuid(),'expectedRevision',0,'method','manual','amountCents',100))$$,'P0001','SHIPPING_FEE_CHANGED','Stale fee edit rejected');
select throws_ok($$select public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('incoming'),'operationId',gen_random_uuid(),'expectedRevision',1,'method','manual','amountCents',-100))$$,'P0001','INVALID_SHIPPING_FEE','Negative amount rejected');
select throws_ok($$select public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('incoming'),'operationId',gen_random_uuid(),'expectedRevision',1,'method','manual','amountCents',150))$$,'P0001','INVALID_SHIPPING_FEE','Centavos rejected');
select throws_ok($$select public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('incoming'),'operationId',gen_random_uuid(),'expectedRevision',1,'method','manual','amountCents','abc'))$$,'P0001','INVALID_SHIPPING_FEE','Letters rejected');
select throws_ok($$select public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('incoming'),'operationId',gen_random_uuid(),'expectedRevision',1,'method','percentage','basisPoints',500,'expectedCostCents',1))$$,'P0001','SHIPPING_FEE_COST_CHANGED','Stale percentage base rejected');
select is(public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('incoming'),'operationId',gen_random_uuid(),'expectedRevision',1,'method','percentage','basisPoints',500,'expectedCostCents',3210000))->>'shippingFeeCents','160500','5 percent of exact cost, rounded once to pesos');
select is((select reserved from public.stock_balances where product_id=pg_temp.id('product')),4,'Editing a fee never changes reservations');
select throws_ok($$select public.transition_order_checked(pg_temp.id('incoming'),'mark_paid',1,610500,3210000)$$,'P0001','ORDER_PAYMENT_AMOUNT_CHANGED','Cobro rejects a changed fee revision');
select throws_ok($$select public.transition_order_checked(pg_temp.id('incoming'),'mark_paid',2,450000,3210000)$$,'P0001','ORDER_PAYMENT_AMOUNT_CHANGED','Cobro rejects a different reviewed total');
select is((select payment_state::text from public.orders where id=pg_temp.id('incoming')),'pending','Stale confirmation does not collect');
select is(public.transition_order_checked(pg_temp.id('incoming'),'mark_paid',2,610500,3210000)->>'totalCents','610500','Payment preserves the reviewed nominal fee');
select throws_ok($$select public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('incoming'),'operationId',gen_random_uuid(),'expectedRevision',2,'method','manual','amountCents',0))$$,'P0001','SHIPPING_FEE_LOCKED','Paid fee is immutable');
select public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('mixed'),'operationId',gen_random_uuid(),'expectedRevision',0,'method','manual','amountCents',1250000));
select is(public.transition_order(pg_temp.id('mixed'),'mark_at_cost')->>'totalCents','4660000','At-cost collects exact merchandise cost plus fee');
select is((select sum((item->>'subtotalCents')::bigint)::bigint from jsonb_array_elements(private.order_payload(pg_temp.id('mixed'),true)->'items') item),3410000::bigint,'Cost-sale line presentation matches exact header');
select is((select total_cents-cost_total_cents-tax_amount_cents from public.orders where id=pg_temp.id('mixed')),1250000::bigint,'Cost-sale shipping is income, not forced zero margin');
insert into fixture values('receipt_input',jsonb_build_array(jsonb_build_object('purchaseItemId',(select value->'items'->0->>'id' from fixture where name='purchase'),'receivedQuantity',2)));
insert into fixture values('receipt_op',to_jsonb(gen_random_uuid()));
insert into fixture values('receipt_result',public.receive_purchase(pg_temp.id('purchase'),(select value from fixture where name='receipt_input'),(select (value#>>'{}')::uuid from fixture where name='receipt_op'),1500000));
select is((select count(*) from public.misc_expenses),1::bigint,'One supplier shipping expense');
select is((select amount_cents from public.misc_expenses),1500000::bigint,'Supplier shipping expense exact');
select is((select count(*) from public.misc_expense_audit),1::bigint,'Supplier expense creation audited');
select ok((select purchase_receipt_operation_id is not null from public.misc_expenses),'Expense linked to receipt');
select is((select on_hand from public.stock_balances where product_id=pg_temp.id('product')),6,'Partial receipt adds only two physical units');
select is((select sum(quantity) from public.stock_reservations where order_id=pg_temp.id('incoming') and source_type='physical'),2::bigint,'Partial arrival converts oldest linked order first');
select is((select sum(quantity) from public.stock_reservations where order_id=pg_temp.id('incoming') and source_type='incoming'),1::bigint,'Unreceived portion remains incoming');
select is(public.receive_purchase(pg_temp.id('purchase'),(select value from fixture where name='receipt_input'),(select (value#>>'{}')::uuid from fixture where name='receipt_op'),1500000),(select value from fixture where name='receipt_result'),'Receipt retry returns exact result');
select is((select on_hand from public.stock_balances where product_id=pg_temp.id('product')),6,'Retry does not duplicate physical stock');
select is((select count(*) from public.misc_expenses),1::bigint,'Retry does not duplicate expense');
select throws_ok($$select public.receive_purchase(pg_temp.id('purchase'),(select value from fixture where name='receipt_input'),(select (value#>>'{}')::uuid from fixture where name='receipt_op'),100)$$,'P0001','IDEMPOTENCY_KEY_REUSE_MISMATCH','Receipt retry cannot change shipping amount');
select throws_ok($$select public.receive_purchase(pg_temp.id('purchase'),(select value from fixture where name='receipt_input'),gen_random_uuid(),-100)$$,'P0001','INVALID_SHIPPING_FEE','Supplier negative shipping rejected');
select throws_ok($$select public.receive_purchase(pg_temp.id('purchase'),(select value from fixture where name='receipt_input'),gen_random_uuid(),101)$$,'P0001','INVALID_SHIPPING_FEE','Supplier centavos rejected');
select public.receive_purchase(pg_temp.id('purchase'),jsonb_build_array(jsonb_build_object('purchaseItemId',(select value->'items'->0->>'id' from fixture where name='purchase'),'receivedQuantity',8)),gen_random_uuid());
select is((select count(*) from public.misc_expenses),1::bigint,'Blank shipping creates no expense');
select is(private.order_payload(pg_temp.id('incoming'),true)->>'stockReadiness','ready','Full arrival unblocks incoming-only order');
select public.transition_order(pg_temp.id('normal'),'mark_paid');
insert into fixture values('gift',public.confirm_imported_order(pg_temp.order_input('normal',1)));
select public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('gift'),'operationId',gen_random_uuid(),'expectedRevision',0,'method','percentage','basisPoints',500,'expectedCostCents',1070000));
select is(public.transition_order(pg_temp.id('gift'),'mark_gifted')->>'totalCents','0','Gift clears entire total including fee');
select is(private.order_payload(pg_temp.id('gift'),true)->>'shippingFeeCents','0','Gift clears fee');
select is(private.order_payload(pg_temp.id('gift'),true)->>'shippingFeeBasisPoints',null,'Gift clears percentage metadata');
create temp table report as select public.get_sales_analytics((now() at time zone 'America/Argentina/Buenos_Aires')::date,(now() at time zone 'America/Argentina/Buenos_Aires')::date) value;
select is((select value->>'orders' from report),'3','Only paid sales counted; gift separate');
select is((select value->>'giftOrders' from report),'1','Gift counted separately');
select is((select value->>'shippingRevenueCents' from report),'1410500','Shipping included once in paid revenue');
select is((select value->>'supplierShippingExpensesCents' from report),'1500000','Supplier expense categorized in period');
select is((select (value->>'costCents')::bigint from report),(select sum(cost_total_cents)::bigint from public.orders where payment_state in ('paid','gifted')),'Exact merchandise costs include gift once');
select is((select (value->>'estimatedMarginCents')::bigint from report),(select sum(total_cents-cost_total_cents-tax_amount_cents)::bigint from public.orders where payment_state in ('paid','gifted'))-1500000,'Net profit independent accounting oracle');
select is((select sum((item->>'revenueCents')::bigint)::bigint from report,jsonb_array_elements(value->'topProducts') item)+(select (value->>'shippingRevenueCents')::bigint from report),(select (value->>'revenueCents')::bigint from report),'Product revenue plus shipping reconciles to paid revenue');
select is((public.ai_get_sales_summary(current_date,current_date)->'facts'->>'sales.supplier_shipping_expenses_cents'),'1500000','AI expense fact agrees with reporting');
select is((public.get_dashboard_summary()->>'miscExpensesMonthCents'),'1500000','Dashboard expense agrees');
select is((select r->>'shippingCostCents' from jsonb_array_elements(public.get_business_export_dataset()->'purchaseReceipts') r where r->>'operationId'=(select value#>>'{}' from fixture where name='receipt_op')),'1500000','Backup retains supplier receipt cost');
select ok(jsonb_array_length(public.get_business_export_dataset()->'orderShippingFeeHistory')>=4,'Backup retains customer fee audit trail');
select is((public.get_business_export_dataset()->'expenses'->0->>'purchaseNumber'),(select value->>'number' from fixture where name='purchase'),'Backup expense keeps supplier purchase provenance');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000101002',true);
select throws_ok($$select public.save_order_shipping_fee('{}')$$,'P0001','FORBIDDEN','Staff cannot edit financial fee');
select throws_ok($$select public.receive_purchase(pg_temp.id('purchase'),'[]',gen_random_uuid(),100)$$,'P0001','FORBIDDEN','Staff cannot register supplier expenses');
select is(private.order_payload(pg_temp.id('incoming'),false)->>'shippingFeeCostBaseCents',null,'Staff order payload hides cost base');
select is(private.order_payload(pg_temp.id('incoming'),false)->>'shippingFeeBasisPoints',null,'Staff cannot infer cost from percentage');
select is(private.order_payload(pg_temp.id('incoming'),false)->>'shippingFeeCents','160500','Staff can see amount to collect');
select throws_ok($$select public.confirm_imported_order(pg_temp.order_input('normal',1)||'{"saleType":"cost"}')$$,'P0001','FORBIDDEN','Staff cannot create cost sales');
select throws_ok($$select public.transition_order_checked(pg_temp.id('normal'),'mark_at_cost',0,300000,200000)$$,'P0001','FORBIDDEN','Checked transition enforces owner before idempotent return');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000101001',true);

-- No-arrival receipts, expense corrections and atomic rollback.
insert into fixture values('extra_purchase',public.create_purchase(jsonb_build_object('supplierName','QA extra','items',jsonb_build_array(jsonb_build_object('productId',pg_temp.id('product'),'quantity',2,'unitCostCents',1070000)))));
insert into fixture values('before_stock',to_jsonb((select on_hand from public.stock_balances where product_id=pg_temp.id('product'))));
select throws_ok($$select public.receive_purchase(pg_temp.id('extra_purchase'),'[]',gen_random_uuid(),0)$$,'P0001','INVALID_INPUT','An empty zero-expense receipt is rejected');
insert into fixture values('expense_only',public.receive_purchase(pg_temp.id('extra_purchase'),'[]',gen_random_uuid(),50000));
select is((select on_hand::text from public.stock_balances where product_id=pg_temp.id('product')),(select value#>>'{}' from fixture where name='before_stock'),'Expense-only receipt does not add units');
select is((select state::text from public.purchases where id=pg_temp.id('extra_purchase')),'ordered','Expense-only receipt keeps merchandise pending');
select is((select value->'shippingExpense'->>'amountCents' from fixture where name='expense_only'),'50000','Expense-only receipt retains its nominal fee');
select throws_ok($$select public.save_misc_expense(jsonb_build_object('id',(select value->'shippingExpense'->>'id' from fixture where name='expense_only'),'expectedUpdatedAt',(select value->'shippingExpense'->>'updatedAt' from fixture where name='expense_only'),'title','QA corregido','amountCents',50000,'frequency','monthly','startsOn',current_date,'endsOn',null))$$,'P0001','INVALID_MISC_EXPENSE','A receipt-linked expense cannot become recurring');
select is(public.save_misc_expense(jsonb_build_object('id',(select value->'shippingExpense'->>'id' from fixture where name='expense_only'),'expectedUpdatedAt',(select value->'shippingExpense'->>'updatedAt' from fixture where name='expense_only'),'title','QA corregido','amountCents',60000,'frequency','once','startsOn',current_date,'endsOn',null))->>'amountCents','60000','Expense correction updates the single linked expense');
select is((public.get_sales_analytics(current_date,current_date)->>'supplierShippingExpensesCents'),'1560000','Corrected expense is used once in the financial balance');
select is((select shipping_cost_cents from public.purchase_receipts where operation_id=(select (value->'shippingExpense'->>'purchaseReceiptOperationId')::uuid from fixture where name='expense_only')),50000::bigint,'Receipt preserves original cost snapshot after an audited correction');
create function pg_temp.fail_shipping_expense() returns trigger language plpgsql as $$ begin if new.purchase_receipt_operation_id is not null then raise exception 'QA_EXPENSE_FAILURE'; end if; return new; end $$;
create trigger qa_expense_failure before insert on public.misc_expenses for each row execute function pg_temp.fail_shipping_expense();
select throws_ok($$select public.receive_purchase(pg_temp.id('extra_purchase'),jsonb_build_array(jsonb_build_object('purchaseItemId',(select value->'items'->0->>'id' from fixture where name='extra_purchase'),'receivedQuantity',1)),gen_random_uuid(),100)$$,'P0001','QA_EXPENSE_FAILURE','A failed expense reverses the entire receipt');
select is((select on_hand::text from public.stock_balances where product_id=pg_temp.id('product')),(select value#>>'{}' from fixture where name='before_stock'),'Failed expense cannot leave physical stock incremented');
select is((select received_quantity from public.purchase_items where purchase_id=pg_temp.id('extra_purchase')),0,'Failed expense cannot leave a received quantity');
drop trigger qa_expense_failure on public.misc_expenses;

-- Tax, zero percent and changed assigned costs are independent of catalog edits.
insert into fixture values('tax_order',public.confirm_imported_order(pg_temp.order_input('normal',1)));
update public.orders set tax_rate_basis_points=1000 where id=pg_temp.id('tax_order');
select is(public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('tax_order'),'operationId',gen_random_uuid(),'expectedRevision',0,'method','manual','amountCents',10000))->>'taxAmountCents','16000','Fee editing recomputes tax using the stored rate');
select public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('tax_order'),'operationId',gen_random_uuid(),'expectedRevision',1,'method','percentage','basisPoints',500,'expectedCostCents',1070000));
update public.orders set cost_total_cents=1070100 where id=pg_temp.id('tax_order');
select is(private.order_payload(pg_temp.id('tax_order'),false)->>'shippingFeeNeedsReview','true','Staff sees required shipping review without exposing financial values');
select ok(private.order_payload(pg_temp.id('tax_order'),false)->'shippingFeeCostBaseCents'='null'::jsonb,'Review flag does not reveal the assigned merchandise cost');
select throws_ok($$select public.transition_order(pg_temp.id('tax_order'),'mark_paid')$$,'P0001','SHIPPING_FEE_COST_CHANGED','An assigned-cost change requires reviewing a positive percentage before cobro');
select is(public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('tax_order'),'operationId',gen_random_uuid(),'expectedRevision',2,'method','percentage','basisPoints',0,'expectedCostCents',1070100))->>'shippingFeeCents','0','Zero percent has a zero nominal fee');
update public.orders set cost_total_cents=1070200 where id=pg_temp.id('tax_order');
select lives_ok($$select public.transition_order(pg_temp.id('tax_order'),'mark_paid')$$,'Zero percent does not block a cobro when the nominal fee stays zero');
select ok(exists(select 1 from public.order_shipping_fee_events where order_id=pg_temp.id('gift') and input_payload->>'action'='mark_gifted'),'Gift clearing has its own financial audit event');
select ok(not has_function_privilege('anon','public.save_order_shipping_fee(jsonb)','execute'),'Public cannot edit customer fees');
select ok(not has_function_privilege('anon','public.receive_purchase(uuid,jsonb,uuid,bigint)','execute'),'Public cannot register supplier expenses');
set local role authenticated;
select ok((select count(*) from public.order_shipping_fee_events)>0,'Owner can read fee history through RLS');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000101002',true);
set local role authenticated;
select is((select count(*) from public.order_shipping_fee_events),0::bigint,'Staff cannot read financial audit history through RLS');
reset role;
-- Cross-check lifecycle against the unchanged list/dashboard reporting contracts.
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000101001',true);
insert into fixture values('before_cancel',public.get_sales_analytics(current_date,current_date));
insert into fixture values('before_cancel_list',public.search_paid_orders(1,1,current_date,current_date));
insert into fixture values('before_cancel_dashboard',public.get_dashboard_summary());
select is(public.transition_order(pg_temp.id('tax_order'),'cancel')->>'paymentState','refunded','Cancelling a paid order marks its existing payment refunded');
select is(public.get_sales_analytics(current_date,current_date)->>'revenueCents',((select (value->>'revenueCents')::bigint from fixture where name='before_cancel')-(select total_cents from public.orders where id=pg_temp.id('tax_order')))::text,'Cancelled refunded payment leaves no active revenue');
select is((public.search_paid_orders(1,1,current_date,current_date)->>'total')::bigint,(select (value->>'total')::bigint-1 from fixture where name='before_cancel_list'),'Paid-order list removes that same refunded order');
select is((public.get_dashboard_summary()->>'paidRevenueMonthCents')::bigint,(select (value->>'paidRevenueMonthCents')::bigint from fixture where name='before_cancel_dashboard')-(select total_cents from public.orders where id=pg_temp.id('tax_order')),'Dashboard removes the same paid amount');
select throws_ok($$select public.save_order_shipping_fee(jsonb_build_object('orderId',pg_temp.id('tax_order'),'operationId',gen_random_uuid(),'expectedRevision',3,'method','manual','amountCents',0))$$,'P0001','SHIPPING_FEE_LOCKED','Cancellation does not reopen the immutable fee');
insert into fixture values('before_refund',public.get_sales_analytics(current_date,current_date));
select is(public.transition_order(pg_temp.id('mixed'),'mark_refunded')->>'paymentState','refunded','Explicit reintegro marks the cost-sale payment refunded');
select is((public.get_sales_analytics(current_date,current_date)->>'revenueCents')::bigint,(select (value->>'revenueCents')::bigint from fixture where name='before_refund')-(select total_cents from public.orders where id=pg_temp.id('mixed')),'Reintegro removes merchandise and customer shipping together');
select is((public.get_sales_analytics(current_date,current_date)->>'costCents')::bigint,(select (value->>'costCents')::bigint from fixture where name='before_refund')-(select cost_total_cents from public.orders where id=pg_temp.id('mixed')),'Reintegro removes the corresponding active merchandise cost');
select is(public.transition_order_checked(pg_temp.id('gift'),'mark_gifted',1,203500,1070000)->>'paymentState','gifted','Checked gift replay accepts the original reviewed revision after its fee was cleared');
select is((select count(*) from public.order_shipping_fee_events where order_id=pg_temp.id('gift')),2::bigint,'Checked gift replay does not add another financial event');
insert into fixture values('manual_gift',public.confirm_imported_order(pg_temp.order_input('normal',1)||'{"saleType":"gift","paymentMethod":"gift"}'::jsonb));
insert into fixture values('before_gift_cancel',public.get_sales_analytics(current_date,current_date));
insert into fixture values('before_gift_cancel_dashboard',public.get_dashboard_summary());
select is(public.transition_order(pg_temp.id('manual_gift'),'cancel')->>'paymentState','refunded','Cancelling an undelivered manual gift reverses its financial recognition');
select is((public.get_sales_analytics(current_date,current_date)->>'costCents')::bigint,(select (value->>'costCents')::bigint from fixture where name='before_gift_cancel')-(select cost_total_cents from public.orders where id=pg_temp.id('manual_gift')),'Cancelled manual gift leaves no phantom merchandise expense');
select is((public.get_sales_analytics(current_date,current_date)->>'giftOrders')::bigint,(select (value->>'giftOrders')::bigint-1 from fixture where name='before_gift_cancel'),'Cancelled manual gift leaves no active gift count');
select is((public.get_dashboard_summary()->>'estimatedMarginMonthCents')::bigint,(select (value->>'estimatedMarginMonthCents')::bigint from fixture where name='before_gift_cancel_dashboard')+(select cost_total_cents from public.orders where id=pg_temp.id('manual_gift')),'Dashboard reverses the same cancelled gift cost');
select * from finish();
rollback;
